    R=len(g);C=len(g[0])
    c5=[(r,c) for r in range(R) for c in range(C) if g[r][c]==5]
    minr=min(r for r,c in c5);maxr=max(r for r,c in c5)
    minc=min(c for r,c in c5);maxc=max(c for r,c in c5)
    for r in range(R):
        for c in range(C):
            if g[r][c]==2:
                opts=[]
                if c>maxc: opts.append((c-maxc,0,-1))
                if c<minc: opts.append((minc-c,0,1))
                if r>maxr: opts.append((r-maxr,-1,0))
                if r<minr: opts.append((minr-r,1,0))
                if not opts: continue
                opts.sort()
                _,dr,dc=opts[0]
                nr,nc=r+dr,c+dc
                while 0<=nr<R and 0<=nc<C and g[nr][nc]!=5:
                    if g[nr][nc]==0: g[nr][nc]=2
                    nr+=dr;nc+=dc
    return g

